  .sources{display:grid;gap:var(--space-4)}.tabs,.actions{display:flex;flex-wrap:wrap;gap:var(--space-2)}button{min-height:44px;padding:0 var(--space-3);border:1px solid var(--color-border);border-radius:var(--radius-control);background:var(--color-surface);color:var(--color-text-primary)}button.active,button.primary{border-color:var(--color-info-border);background:var(--color-info-subtle)}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:var(--space-3)}article,aside,[role=alert]{display:grid;gap:var(--space-3);padding:var(--space-4);border:1px solid var(--color-border);border-radius:var(--radius-card);background:var(--color-surface)}article.selected{border-color:var(--color-info-border)}h2,h3,p{margin:0}p,code{color:var(--color-text-muted)}.fusion-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(280px,360px);gap:var(--space-4);align-items:start}aside{position:sticky;top:var(--space-3)}@media(max-width:850px){.fusion-layout{grid-template-columns:1fr}aside{position:static}}
